using System.Numerics;

namespace Erlang;

public static class CoreModules
{
    public static void Register(ModuleRegistry r)
    {
        r.InstallPreloaded(RegisterCode);
    }

    private static void RegisterCode(ModuleRegistry r)
    {
        void Add(
