            ErlangModuleNames.IsAtom,
            1,
            (c, a) => Boolean(a[0] is Atom)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsInteger,
            1,
            (c, a) => Boolean(a[0] is Integer)
        );
        Add(
            ErlangModuleNames.Module,
            ErlangModuleNames.IsFloat,
            1,
            (c, a) => Boolean(a[0] is FloatTerm)
        );
        Add(
