                    s,
                    record.Module,
                    depth + 1,
                    options
                );
                Write(
                    s,
                    record.Name,
                    depth + 1,
                    options
                );
                foreach (var field in record.FieldNames)
                    Write(
                        s,
                        field,
                        depth + 1,
                        options
                    );
                foreach (var value in record.Values)
                    Write(
                        s,
                        value,
                        depth + 1,
                        options
                    );
