                        f.LocalIdentity.Module,
                        depth + 1,
                        options
                    );
                    Write(
                        s,
                        Term.I(f.LocalIdentity.OldIndex),
                        depth + 1,
                        options
                    );
                    Write(
                        s,
                        Term.I(f.LocalIdentity.OldUnique),
                        depth + 1,
                        options
