namespace Erlang;

public static class ReferenceIdentityLayout
{
    public const int WordBits = 32;
    public const int MinimumWords = 1;
    public const int MaximumWords = 5;
    public const int LocalWords = 3;
    public const int LocalFirstWordBits = 18;
    public const int PidMarkerWord = 1;
    public const int PidMarkerBitOffset = 2;
    public const uint PidMarker = 1u << (LocalFirstWordBits - PidMarkerBitOffset);
    public const int PidWordCount = 5;
    public const int PidTagBits = 4;
    public const uint PidTagMask = (1u << PidTagBits) - 1;
    public const uint PidTag = 3;
    public const int PidOwnerLowWord = 3;
    public const int PidOwnerHighWord = 4;
    public const uint LocalFirstWordMask = (1u << LocalFirstWordBits) - 1;
}

using System.Reflection;
using System.IO.Compression;

namespace Erlang.Tests;

public static class BeamLoaderAdmissionChecks
{
    public static async Task Run()
    {
        await using var runtime = new ProcessRuntime();
        await using var foreign = new ProcessRuntime();
        var completed = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        ProcessHandle actor = runtime.Spawn(async context =>
        {
            try
            {
                byte[] bytes = Resource(BeamPreparedHostNames.Constant + BeamLoaderAdmissionNames.Extension);
                Term module = Term.A(BeamPreparedHostNames.Constant);
                Term reference = await Call(
                    context,
                    BeamLoaderAdmissionNames.Prepare,
                    module,
                    new BitString(bytes)
                );
                Require(reference is ResourceReferenceTerm);
                Require((await Call(context, BeamLoaderAdmissionNames.Query, reference)).Equals(Term.A(ErlangBooleanAtoms.False)));
                Require((await Call(context, BeamLoaderAdmissionNames.Finish, Cons.From([reference]))).Equals(Term.A(BeamLoaderAdmissionNames.Ok)));
                Require((await Call(context, BeamLoaderAdmissionNames.Query, reference)).Equals(Term.A(ErlangBooleanAtoms.False)));
                Require(runtime.ReferenceResources.AcquirePrepared((ReferenceTerm)reference) is null);
                await Badarg(() => Call(context, BeamLoaderAdmissionNames.Finish, Cons.From([reference])));
                ResourceReferenceTerm wrongOwner = foreign.ReferenceResources.CreatePrepared(foreign.Modules.PrepareBeam(bytes));
                await Badarg(() => Call(context, BeamLoaderAdmissionNames.Query, wrongOwner));
                await Badarg(() => Call(context, BeamLoaderAdmissionNames.Finish, Cons.From([wrongOwner])));
                ResourceReferenceTerm wrongKind = runtime.ReferenceResources.CreateBinary(bytes);
                await Badarg(() => Call(context, BeamLoaderAdmissionNames.Query, wrongKind));
                Term fresh = await Call(
                    context,
                    BeamLoaderAdmissionNames.Prepare,
                    module,
                    new BitString(bytes)
                );
                await Badarg(() => Call(context, BeamLoaderAdmissionNames.Finish, new Cons(fresh, Term.I(1))));
                Require(runtime.ReferenceResources.AcquirePrepared((ReferenceTerm)fresh) is not null);
                Require((await Call(
                    context,
                    BeamLoaderAdmissionNames.Prepare,
                    Term.A(BeamLoaderAdmissionNames.ForeignModule),
                    new BitString(bytes)
                ))
                    .Equals(Term.Tuple(Term.A(BeamLoaderAdmissionNames.Error), Term.A(BeamLoaderAdmissionNames.BadFile))));
                using var compressed = new MemoryStream();
                using (var gzip = new GZipStream(compressed, CompressionMode.Compress, true))
                    gzip.Write(bytes);
                await GzipErrorArguments(context, compressed.ToArray(), bytes);
                byte[] unsupportedOnLoad = Resource(BeamPreparedHostNames.OnLoad + BeamLoaderAdmissionNames.Extension);
                try
                {
                    await Call(
                        context,
                        BeamLoaderAdmissionNames.Prepare,
                        Term.A(BeamPreparedHostNames.OnLoad),
                        new BitString(unsupportedOnLoad)
                    );
                    throw new InvalidOperationException(BeamLoaderAdmissionNames.Failure);
                }
                catch (NotSupportedException)
                {
                }
                byte[] onLoad = Resource(BeamLoaderAdmissionNames.SupportedOnLoadResource);
                Term callbackModule = Term.A(BeamOnLoadHostNames.FreshSuccessModule);
                Term callbackReference = await Call(
                    context,
                    BeamLoaderAdmissionNames.Prepare,
                    callbackModule,
                    new BitString(onLoad)
                );
                await Reject(ErlangErrorReasons.SystemLimit, () => Call(context, BeamLoaderAdmissionNames.Finish, Cons.From([fresh, callbackReference])));
                Require(runtime.ReferenceResources.AcquirePrepared((ReferenceTerm)fresh) is not null && runtime.ReferenceResources.AcquirePrepared((ReferenceTerm)callbackReference) is not null);
                Require((await Call(context, BeamLoaderAdmissionNames.Finish, Cons.From([callbackReference])))
                    .Equals(Term.Tuple(Term.A(BeamLoaderAdmissionNames.OnLoad), Cons.From([callbackModule]))));
                Require((await Call(context, BeamLoaderAdmissionNames.Query, callbackReference)).Equals(Term.A(ErlangBooleanAtoms.True)));
                for (int repeat = 0; repeat < 2; repeat++)
                    Require((await Call(
                        context,
                        BeamLoaderAdmissionNames.FinishOnLoad,
                        callbackModule,
                        Term.A(ErlangBooleanAtoms.False)
                    )).Equals(Term.A(ErlangBooleanAtoms.True)));
                Require((await Call(
                    context,
                    BeamLoaderAdmissionNames.FinishOnLoad,
                    callbackModule,
                    Term.A(ErlangBooleanAtoms.True)
                )).Equals(Term.A(ErlangBooleanAtoms.True)));
                await Badarg(() => Call(
                    context,
                    BeamLoaderAdmissionNames.FinishOnLoad,
                    callbackModule,
                    Term.A(ErlangBooleanAtoms.True)
                ));
                completed.TrySetResult();

                return Term.A(ErlangBooleanAtoms.True);
            }
            catch (Exception exception)
            {
                completed.TrySetException(exception);
                throw;
            }
        });
        await completed.Task;
        await actor.Completion;
        await ClosedResourceAdmission();
    }

    private static async Task ClosedResourceAdmission()
    {
        var runtime = new ProcessRuntime();
        PreparedBeamImage image = runtime.Modules.PrepareBeam(Resource(BeamPreparedHostNames.Constant + BeamLoaderAdmissionNames.Extension));
        ResourceReferenceTerm reference = runtime.ReferenceResources.CreatePrepared(image);
        await runtime.DisposeAsync();
        MethodInfo finish = typeof(RuntimeReferenceResources).GetMethod(BeamLoaderAdmissionNames.Admit, BindingFlags.Instance | BindingFlags.NonPublic)!;
        try
        {
            finish.Invoke(runtime.ReferenceResources, [new ReferenceTerm[] { reference }]);
        }
        catch (TargetInvocationException exception) when (exception.InnerException is ErlangException error)
        {
            Require(error.Reason.Equals(Term.A(ErlangErrorReasons.BadArgument)) && !image.IsConsumed);

            return;
        }

        throw new InvalidOperationException(BeamLoaderAdmissionNames.Failure);
    }

    private static async Task GzipErrorArguments(ProcessContext context, byte[] gzip, byte[] original)
    {
        try
        {
            await Call(
                context,
                BeamLoaderAdmissionNames.Prepare,
                Term.I(1),
                new BitString(gzip)
            );
        }
        catch (ErlangException exception)
        {
            Require(exception.Reason.Equals(Term.A(ErlangErrorReasons.BadArgument)));
            var frame = (TupleTerm)Cons.Items(exception.StackTraceTerm).First();
            Term[] arguments = Cons.Items(frame.Items[2]).ToArray();
            Require(arguments[1].Equals(new BitString(original)));
            var location = (TupleTerm)Cons.Items(frame.Items[3]).First();
            Require(location.Items[0].Equals(Term.A(BeamLoaderAdmissionNames.ErrorInfo)));
            var info = (MapTerm)location.Items[1];
            Require(info.Entries.Any(entry => entry.Key.Equals(Term.A(BeamLoaderAdmissionNames.Module)) && entry.Value.Equals(Term.A(BeamLoaderAdmissionNames.Formatter))));

            return;
        }

        throw new InvalidOperationException(BeamLoaderAdmissionNames.Failure);
    }

    private static ValueTask<Term> Call(ProcessContext context, string name, params Term[] arguments)
        => context.Runtime.Modules.Call(
            context,
            ErlangModuleNames.Module,
            name,
            arguments
        );

    private static Task Badarg(Func<ValueTask<Term>> execute) => Reject(ErlangErrorReasons.BadArgument, execute);

    private static async Task Reject(string reason, Func<ValueTask<Term>> execute)
    {
        try
        {
            await execute();
        }
        catch (ErlangException exception)
        {
            Require(exception.Reason.Equals(Term.A(reason)));

            return;
        }

        throw new InvalidOperationException(BeamLoaderAdmissionNames.Failure);
    }

    private static byte[] Resource(string name)
    {
        Assembly assembly = typeof(BeamLoaderAdmissionChecks).Assembly;
        string path = assembly.GetManifestResourceNames().Single(value => value.EndsWith(BeamLoaderAdmissionNames.Separator + name, StringComparison.Ordinal));
        using Stream stream = assembly.GetManifestResourceStream(path)!;
        using var output = new MemoryStream();
        stream.CopyTo(output);

        return output.ToArray();
    }

    private static void Require(bool value)
    {
        if (!value)
            throw new InvalidOperationException(BeamLoaderAdmissionNames.Failure);
    }
}

namespace Erlang.Tests;

internal static class BeamLoaderAdmissionNames
{
    internal const string SupportedOnLoadResource = "fresh_success.new.beam_on_load_fresh_success.beam";
    internal const string Admit = "FinishPreparedReferences";
    internal const string Ok = "ok";
    internal const string Failure = "Loader typed resource admission contract failed";
    internal const string RuntimeNamespace = "Erlang";
    internal const string Prepare = "prepare_loading";
    internal const string Query = "has_prepared_code_on_load";
    internal const string Finish = "finish_loading";
    internal const string OnLoad = "on_load";
    internal const string FinishOnLoad = "finish_after_on_load";
    internal const string Error = "error";
    internal const string Module = "module";
    internal const string ErrorInfo = "error_info";
    internal const string Formatter = "erl_erts_errors";
    internal const string BadFile = "badfile";
    internal const string ForeignModule = "loader_wrong_module";
    internal const string Extension = ".beam";
    internal const string Separator = ".";
    internal const string Missing = "loader_missing";
}

using System.Reflection;

namespace Erlang.Tests;

public static class BeamLoaderAdmissionRaceChecks
{
    public static async Task Run(byte[] bytes)
    {
        await CompetingConsume(bytes);
        await ClosedBeforeAdmission(bytes);
    }

    private static async Task CompetingConsume(byte[] bytes)
    {
        await using var runtime = new ProcessRuntime();
        PreparedBeamImage image = runtime.Modules.PrepareBeam(bytes);
        ResourceReferenceTerm reference = runtime.ReferenceResources.CreatePrepared(image);
        using var started = new ManualResetEventSlim();
        object moduleGate = typeof(ModuleRegistry).GetField(BeamLoaderAdmissionRaceNames.ModuleGate, BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(runtime.Modules)!;
        Task<Term> competing;
        Monitor.Enter(moduleGate);
        try
        {
            competing = Task.Run(() =>
            {
                started.Set();

                return Finish(runtime.ReferenceResources, reference);
            });
            Require(started.Wait(TimeSpan.FromSeconds(BeamLoaderAdmissionRaceNames.WatchdogSeconds)));
            Require(runtime.Modules.PublishPreparedBeam(image).Status == BeamPublicationStatus.Published);
        }
        finally
        {
            Monitor.Exit(moduleGate);
        }
        await Badarg(competing);
        Require(image.IsConsumed);
    }

    private static async Task ClosedBeforeAdmission(byte[] bytes)
    {
        var runtime = new ProcessRuntime();
        PreparedBeamImage image = runtime.Modules.PrepareBeam(bytes);
        ResourceReferenceTerm reference = runtime.ReferenceResources.CreatePrepared(image);
        using var started = new ManualResetEventSlim();
        object moduleGate = typeof(ModuleRegistry).GetField(BeamLoaderAdmissionRaceNames.ModuleGate, BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(runtime.Modules)!;
        Task<Term> competing;
        Monitor.Enter(moduleGate);
        try
        {
            competing = Task.Run(() =>
            {
                started.Set();

                return Finish(runtime.ReferenceResources, reference);
            });
            Require(started.Wait(TimeSpan.FromSeconds(BeamLoaderAdmissionRaceNames.WatchdogSeconds)));
            runtime.DisposeAsync().AsTask().GetAwaiter().GetResult();
        }
        finally
        {
            Monitor.Exit(moduleGate);
        }
        await Badarg(competing);
        Require(!image.IsConsumed && runtime.ReferenceResources.LiveResources == 0);
    }

    private static Term Finish(RuntimeReferenceResources resources, ReferenceTerm reference)
    {
        MethodInfo method = typeof(RuntimeReferenceResources).GetMethod(BeamLoaderAdmissionRaceNames.FinishReferences, BindingFlags.Instance | BindingFlags.NonPublic)!;
        try
        {
            return (Term)method.Invoke(resources, [new ReferenceTerm[] { reference }])!;
        }
        catch (TargetInvocationException exception) when (exception.InnerException is ErlangException error)
        {
            throw error;
        }
    }

    private static async Task Badarg(Task<Term> task)
    {
        try
        {
            await task.WaitAsync(TimeSpan.FromSeconds(BeamLoaderAdmissionRaceNames.WatchdogSeconds));
        }
        catch (ErlangException exception)
        {
            Require(exception.Reason.Equals(Term.A(ErlangErrorReasons.BadArgument)));

            return;
        }

        throw new InvalidOperationException(BeamLoaderAdmissionRaceNames.Failure);
    }

    private static void Require(bool value)
    {
        if (!value)
            throw new InvalidOperationException(BeamLoaderAdmissionRaceNames.Failure);
    }
}

namespace Erlang.Tests;

internal static class BeamLoaderAdmissionRaceNames
{
    internal const string FinishReferences = "FinishPreparedReferences";
    internal const string ModuleGate = "gate";
    internal const string Entered = "entered";
    internal const string Failure = "Loader consumption and closure admission race failed";
    internal const int WatchdogSeconds = 10;
}

using System.Reflection;
using Erlang.Compiler;
using Erlang.Differential;

namespace Erlang.Tests;

public static class BeamLoaderDirectChecks
{
    public static async Task Run()
    {
        await Observe(false, false, false);
        await Observe(true, false, false);
        await Observe(false, true, false);
        await Observe(true, true, false);
    }

    public static async Task RunNative()
    {
        await Observe(false, false, true);
        await Observe(false, true, true);
    }

    private static async Task Observe(bool generated, bool old, bool nativeCaller)
    {
        await using var runtime = new ProcessRuntime();
        using GeneratedModuleArtifact? artifact = generated ? GeneratedModuleCompiler.Compile(BeamLoaderDirectNames.Source) : null;
        ModuleDefinition caller = artifact?.Definition ?? new Parser(BeamLoaderDirectNames.Source).ParseModule();
        caller.Register(runtime.Modules);
        string module = old ? BeamOnLoadHostNames.ReplacementFailureModule : BeamOnLoadHostNames.FreshSuccessModule;
        if (old)
            Require(runtime.Modules.PublishPreparedBeam(runtime.Modules.PrepareBeam(Resource(BeamLoaderDirectNames.ReplacementOldResource))).Status == BeamPublicationStatus.Published);
        var ready = new TaskCompletionSource<ProcessContext>(TaskCreationOptions.RunContinuationsAsynchronously);
        var finish = new TaskCompletionSource<Term>(TaskCreationOptions.RunContinuationsAsynchronously);
        ProcessHandle observer = runtime.Spawn(context =>
        {
            ready.TrySetResult(context);

            return new ValueTask<Term>(finish.Task);
        });
        ProcessContext controller = await ready.Task;
        runtime.Register(BeamOnLoadHostNames.Observer, observer.Pid);
        Term reference = await runtime.Modules.Call(
            controller,
            ErlangModuleNames.Module,
            BeamLoaderAdmissionNames.Prepare,
            Term.A(module),
            new BitString(Resource(old ? BeamLoaderDirectNames.ReplacementNewResource : BeamLoaderDirectNames.FreshResource))
        );
        await runtime.Modules.Call(
            controller,
            ErlangModuleNames.Module,
            BeamLoaderAdmissionNames.Finish,
            Cons.From([reference])
        );
        var callbackReady = new TaskCompletionSource<ProcessContext>(TaskCreationOptions.RunContinuationsAsynchronously);
        object pendingTable = typeof(ModuleRegistry).GetField(BeamLoaderDirectNames.PendingTable, BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(runtime.Modules)!;
        var pending = (System.Collections.IDictionary)pendingTable;
        object ticket = pending[module]!;
        var callbackImage = (ModuleCodeImage)ticket.GetType().GetProperty(BeamLoaderDirectNames.ImageProperty, BindingFlags.Instance | BindingFlags.NonPublic)!.GetValue(ticket)!;
        MethodInfo executing = typeof(ProcessContext).GetMethod(BeamLoaderDirectNames.ExecutingMethod, BindingFlags.Instance | BindingFlags.NonPublic)!;
        var observed = new TaskCompletionSource<Term>(TaskCreationOptions.RunContinuationsAsynchronously);
        ProcessHandle callback = runtime.Spawn(async context =>
        {
            callbackReady.TrySetResult(context);
            try
            {
                Term value = nativeCaller
                    ? await BeamModule.Prepare(Resource(BeamLoaderDirectNames.NativeWrapperResource)).Invoke(context, BeamLoaderDirectNames.Direct, Term.A(module))
                    : await runtime.Modules.Call(
                        context,
                        BeamLoaderDirectNames.Module,
                        BeamLoaderDirectNames.Direct,
                        Term.A(module)
                    );
                Require(!(bool)executing.Invoke(context, [callbackImage])!);
                observed.TrySetResult(value);

                return value;
            }
            catch (Exception exception)
            {
                observed.TrySetException(exception);
                throw;
            }
        });
        try
        {
            TupleTerm notice = (TupleTerm)(await controller.ReceiveAsync(
                term => term is TupleTerm tuple && tuple.Items.Count == 5 && tuple.Items[0].Equals(Term.A(BeamOnLoadHostNames.Notice)) ? term : null,
                TimeSpan.FromSeconds(BeamLoaderDirectNames.WatchdogSeconds)
            ))!;
            if (notice is null && observed.Task.IsCompleted)
                await observed.Task;
            if (notice is null)
                throw new InvalidOperationException(BeamLoaderDirectNames.Failure);
            Require(notice.Items[1].Equals(Term.A(module)) && notice.Items[2].Equals(callback.Pid));
            ProcessContext callbackContext = await callbackReady.Task;
            Require((bool)executing.Invoke(callbackContext, [callbackImage])!);
            Require((await runtime.Modules.Call(
                controller,
                ErlangModuleNames.Module,
                BeamLoaderAdmissionNames.FinishOnLoad,
                Term.A(module),
                Term.A(ErlangBooleanAtoms.False)
            )).Equals(Term.A(ErlangBooleanAtoms.True)));
            Require((bool)executing.Invoke(callbackContext, [callbackImage])!);
            Require(runtime.Modules.IsModuleLoaded(module) == old);
            if (old)
                Require((await runtime.Modules.Call(controller, module, BeamOnLoadHostNames.Run)).Equals(Term.A(BeamOnLoadHostNames.OldImage)));
            await DynamicReject(controller, module);
            Require(await controller.ReceiveAsync(
                term => term is TupleTerm tuple && tuple.Items.Count == 5 && tuple.Items[0].Equals(Term.A(BeamOnLoadHostNames.Notice)) ? term : null,
                TimeSpan.Zero
            ) is null);
            runtime.Send(callback.Pid, Term.Tuple(Term.A(BeamOnLoadHostNames.Continue), observer.Pid));
            Require((await observed.Task.WaitAsync(TimeSpan.FromSeconds(BeamLoaderDirectNames.WatchdogSeconds)))
                .Equals(Term.A(old ? BeamOnLoadHostNames.NotOk : BeamOnLoadHostNames.Ok)));
            Require((await callback.Completion.WaitAsync(TimeSpan.FromSeconds(BeamLoaderDirectNames.WatchdogSeconds)))
                .Equals(Term.A(ProcessExitReasons.Normal)));
            Require((await runtime.Modules.Call(
                controller,
                ErlangModuleNames.Module,
                BeamLoaderAdmissionNames.FinishOnLoad,
                Term.A(module),
                Term.A(ErlangBooleanAtoms.False)
            )).Equals(Term.A(ErlangBooleanAtoms.True)));
            if (old)
                Require((await runtime.Modules.Call(controller, module, BeamOnLoadHostNames.Run)).Equals(Term.A(BeamOnLoadHostNames.OldImage)));
            Require((await runtime.Modules.Call(
                controller,
                ErlangModuleNames.Module,
                BeamLoaderAdmissionNames.FinishOnLoad,
                Term.A(module),
                Term.A(ErlangBooleanAtoms.True)
            )).Equals(Term.A(ErlangBooleanAtoms.True)));
            Require((await runtime.Modules.Call(controller, module, BeamOnLoadHostNames.Run)).Equals(Term.A(BeamOnLoadHostNames.NewImage)));
            Require((await runtime.Modules.Call(
                controller,
                ErlangModuleNames.Module,
                BeamLoaderAdmissionNames.Query,
                reference
            )).Equals(Term.A(ErlangBooleanAtoms.True)));
        }
        finally
        {
            finish.TrySetResult(Term.A(ErlangBooleanAtoms.True));
        }
    }

    private static async Task DynamicReject(ProcessContext context, string module)
    {
        try
        {
            await context.Runtime.Modules.Call(
                context,
                BeamLoaderDirectNames.Module,
                BeamLoaderDirectNames.Dynamic,
                Term.A(ErlangModuleNames.Module),
                Term.A(BeamLoaderDirectNames.Callback),
                Cons.From([Term.A(module)])
            );
        }
        catch (ErlangException exception)
        {
            Require(exception.ExceptionClass == ErlangExceptionClasses.Error && exception.Reason.Equals(Term.A(ErlangErrorReasons.BadArgument)));

            return;
        }

        throw new InvalidOperationException(BeamLoaderDirectNames.Failure);
    }

    private static byte[] Resource(string name)
    {
        Assembly assembly = typeof(BeamLoaderDirectChecks).Assembly;
        string resource = assembly.GetManifestResourceNames().Single(value => value.EndsWith(BeamLoaderAdmissionNames.Separator + name, StringComparison.Ordinal));
        using Stream stream = assembly.GetManifestResourceStream(resource)!;
        using var output = new MemoryStream();
        stream.CopyTo(output);

        return output.ToArray();
    }

    private static void Require(bool value)
    {
        if (!value)
            throw new InvalidOperationException(BeamLoaderDirectNames.Failure);
    }
}

