         down = await c.ReceiveAsync(t => t is TupleTerm x && x.Items[0].Equals(Term.A("DOWN")) && x.Items[1].Equals(reference) ? x : null, TimeSpan.FromSeconds(2));

         return Term.A("ok");
     });
